window.__code__["code-w06-mcp-client-py"] = {"code_id": "code-w06-mcp-client-py", "kind": "local", "title": "mcp_client.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w06/mcp_client.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w06/mcp_client.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W06 作业2:用 MCPClient 接入一个现成 MCP Server,动态发现工具</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 用法对照 examples/agent_service/main.py 的真实写法</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置:</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\">#   export DASHSCOPE_API_KEY=\u00005\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\">#   需要 Node.js(npx) 来拉起 @playwright/mcp。若没有 node,本脚本会在 list_tools 处失败,</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\">#   你可换成本地已有 MCP server,或先读控制流程理解。</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w06/mcp_client.py</span></span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-com\"># 预期:  先打印发现的 MCP 工具名列表,Agent 调 playwright 工具完成操作</span></span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.agent <span class=\"c-kw\">import</span> Agent, ReActConfig</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.credential <span class=\"c-kw\">import</span> DashScopeCredential</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.message <span class=\"c-kw\">import</span> UserMsg</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.mcp <span class=\"c-kw\">import</span> MCPClient, StdioMCPConfig</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.model <span class=\"c-kw\">import</span> DashScopeChatModel</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.permission <span class=\"c-kw\">import</span> PermissionContext, PermissionMode</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.state <span class=\"c-kw\">import</span> AgentState</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.tool <span class=\"c-kw\">import</span> Toolkit</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> main() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    <span class=\"c-com\"># MCPClient 是 pydantic model,字段直接构造</span></span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    <span class=\"c-com\"># Stdio 模式必须 is_stateful=True(框架校验)</span></span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    mcp = MCPClient(</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">        name=<span class=\"c-str\">&quot;playwright&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">        mcp_config=StdioMCPConfig(</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">            command=<span class=\"c-str\">&quot;npx&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">            args=[<span class=\"c-str\">&quot;@playwright/mcp@latest&quot;</span>],</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">        ),</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">        is_stateful=<span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">        execution_timeout=30.0,</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">    <span class=\"c-com\"># 有状态连接必须显式 connect;放 try/finally 保证 close</span></span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    <span class=\"c-kw\">await</span> mcp.connect()</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">        tools = <span class=\"c-kw\">await</span> mcp.list_tools()  <span class=\"c-com\"># 动态发现远端工具 -&gt; list[ToolBase]</span></span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">        print(f<span class=\"c-str\">&quot;🔍 发现 MCP 工具({len(tools)} 个): {[t.name for t in tools]}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> tools:</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">            print(<span class=\"c-str\">&quot;⚠️ 未发现工具(MCP server 未正常启动?)，退出。&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">        model = DashScopeChatModel(</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">            credential=DashScopeCredential(api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>]),</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">            model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">            stream=<span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">        state = AgentState()</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">        state.permission_context = PermissionContext(</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">            permission_mode=PermissionMode.BYPASS  <span class=\"c-com\"># MCP 工具默认 ASK,教学直跑设 BYPASS</span></span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">        agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">            name=<span class=\"c-str\">&quot;web&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">            system_prompt=<span class=\"c-str\">&quot;你能操作浏览器，用提供的 MCP 工具完成任务。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">            model=model,</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">            toolkit=Toolkit(tools=tools),</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">            react_config=ReActConfig(max_iters=10),</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">            state=state,</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> e <span class=\"c-kw\">in</span> agent.reply_stream(</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">            UserMsg(<span class=\"c-str\">&quot;u&quot;</span>, <span class=\"c-str\">&quot;打开 example.com 并告诉我页面标题。&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        ):</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> e.type.value == <span class=\"c-str\">&quot;TEXT_BLOCK_DELTA&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">                print(e.delta, end=<span class=\"c-str\">&quot;&quot;</span>, flush=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">        print()</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    <span class=\"c-kw\">finally</span>:</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> mcp.close()  <span class=\"c-com\"># 别忘了关,否则子进程泄漏</span></span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">    asyncio.run(main())</span></div>\n</div>", "lines": 76, "explanation": "mcp_client.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W06-工具体系与MCP"]};
